
CREATE INDEX ix_retired_notification_source ON core.command_receipt(workspace_id,(result_json->>'sourceKeyHash')) WHERE command_type='portability.retire_notification';
CREATE FUNCTION ops.notification_source_key(kind text,source_id uuid,source_generation integer,rule_generation integer,offset_days integer,local_time text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(jsonb_build_array(kind,source_id,source_generation,rule_generation,offset_days,local_time)::text,'UTF8')),'hex') $$;
REVOKE ALL ON FUNCTION ops.notification_source_key(text,uuid,integer,integer,integer,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ops.notification_source_key(text,uuid,integer,integer,integer,text) TO app_domain,worker_domain;
CREATE FUNCTION ops.notification_generation_retired(kind text,source_id uuid,source_generation integer,rule_generation integer,offset_days integer,local_time text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND c.command_type='portability.retire_notification' AND c.result_json->>'sourceKeyHash'=ops.notification_source_key(kind,source_id,source_generation,rule_generation,offset_days,local_time)) $$;
REVOKE ALL ON FUNCTION ops.notification_generation_retired(text,uuid,integer,integer,integer,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ops.notification_generation_retired(text,uuid,integer,integer,integer,text) TO app_domain,worker_domain;
CREATE POLICY h_provider_proof ON time.notification_attempt FOR SELECT TO migration_owner USING(workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM core.workspace w WHERE w.id=workspace_id AND w.owner_user_id=NULLIF(current_setting('app.user_id',true),'')::uuid));
CREATE POLICY h_provider_proof ON time.notification_provider_event FOR SELECT TO migration_owner USING(workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM core.workspace w WHERE w.id=workspace_id AND w.owner_user_id=NULLIF(current_setting('app.user_id',true),'')::uuid));
CREATE FUNCTION ops.provider_history_known(kind text,portable_row jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE data jsonb;typed jsonb;col record;known boolean;BEGIN
 IF kind NOT IN ('time.notification_attempt','time.notification_provider_event') THEN RAISE EXCEPTION 'unsupported provider proof kind';END IF;
 data:=ops.remap_owner_json(portable_row,NULLIF(current_setting('app.user_id',true),'')::uuid,NULLIF(current_setting('app.workspace_id',true),'')::uuid);
 FOR col IN SELECT attname FROM pg_attribute WHERE attrelid=kind::regclass AND atttypid='bytea'::regtype AND attnum>0 AND NOT attisdropped LOOP IF data->col.attname<>'null'::jsonb THEN data:=jsonb_set(data,ARRAY[col.attname],to_jsonb('\x'||(data->>col.attname)));END IF;END LOOP;
 EXECUTE format('SELECT to_jsonb(p) FROM jsonb_populate_record(NULL::%I.%I,$1) p',split_part(kind,'.',1),split_part(kind,'.',2)) INTO typed USING data;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I t WHERE workspace_id=$1 AND id=($2->>''id'')::uuid AND to_jsonb(t)=$2)',split_part(kind,'.',1),split_part(kind,'.',2)) INTO known USING NULLIF(current_setting('app.workspace_id',true),'')::uuid,typed;
 IF known THEN RETURN true;END IF;
 RETURN EXISTS(SELECT 1 FROM core.command_receipt c CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.result_json->'providerEvidence'->kind,'[]'::jsonb)) e WHERE c.workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND c.command_type='portability.retire_notification' AND e=typed)
 OR EXISTS(SELECT 1 FROM ops.restore_run r CROSS JOIN LATERAL jsonb_array_elements(COALESCE(r.recovery_json->'entities'->kind,'[]'::jsonb)) e WHERE r.workspace_id=NULLIF(current_setting('app.workspace_id',true),'')::uuid AND r.expires_at>clock_timestamp() AND e=typed);
 END $$;
REVOKE ALL ON FUNCTION ops.provider_history_known(text,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION ops.provider_history_known(text,jsonb) TO app_domain;
CREATE FUNCTION ops.preserve_notification_effects() RETURNS integer LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE scope uuid:=NULLIF(current_setting('app.workspace_id',true),'')::uuid;r record;evidence jsonb;result jsonb;key text;hash text;cid uuid;n integer:=0;BEGIN
 IF NOT ops.restore_scope_allowed(scope) THEN RAISE EXCEPTION 'confirmed restore required';END IF;
 IF EXISTS(SELECT 1 FROM time.notification_delivery WHERE workspace_id=scope AND status='attempted') THEN RAISE EXCEPTION 'external delivery unresolved';END IF;
 FOR r IN SELECT o.*,rr.offset_days,substring(rr.local_time::text,1,5) local_time FROM time.reminder_occurrence o JOIN time.reminder_rule rr ON rr.workspace_id=o.workspace_id AND rr.id=o.rule_id WHERE o.workspace_id=scope AND EXISTS(SELECT 1 FROM time.notification_delivery d JOIN time.notification_attempt a ON a.workspace_id=d.workspace_id AND a.delivery_id=d.id WHERE d.workspace_id=o.workspace_id AND d.reminder_occurrence_id=o.id) LOOP
 key:=ops.notification_source_key(CASE WHEN r.personal_event_id IS NOT NULL THEN 'personal_event' WHEN r.application_event_id IS NOT NULL THEN 'application_event' WHEN r.debt_obligation_id IS NOT NULL THEN 'debt_obligation' WHEN r.card_statement_id IS NOT NULL THEN 'card_statement' WHEN r.card_installment_id IS NOT NULL THEN 'card_installment' ELSE 'expected_occurrence' END,COALESCE(r.personal_event_id,r.application_event_id,r.debt_obligation_id,r.card_statement_id,r.card_installment_id,r.expected_occurrence_id),r.source_generation,r.rule_generation,r.offset_days,r.local_time);
 SELECT jsonb_build_object('time.notification_attempt',COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM time.notification_attempt a JOIN time.notification_delivery d ON d.workspace_id=a.workspace_id AND d.id=a.delivery_id WHERE d.workspace_id=scope AND d.reminder_occurrence_id=r.id),'[]'::jsonb),'time.notification_provider_event',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM time.notification_provider_event e JOIN time.notification_attempt a ON a.workspace_id=e.workspace_id AND a.id=e.attempt_id JOIN time.notification_delivery d ON d.workspace_id=a.workspace_id AND d.id=a.delivery_id WHERE d.workspace_id=scope AND d.reminder_occurrence_id=r.id),'[]'::jsonb)) INTO evidence;
 result:=jsonb_build_object('sourceKeyHash',key,'providerEvidence',evidence);hash:=encode(sha256(convert_to(scope::text||ops.canonical_json(result),'UTF8')),'hex');cid:=(substring(hash,1,8)||'-'||substring(hash,9,4)||'-5'||substring(hash,14,3)||'-a'||substring(hash,18,3)||'-'||substring(hash,21,12))::uuid;
 INSERT INTO core.command_receipt(workspace_id,client_command_id,command_type,payload_hash,state,result_json,completed_at)VALUES(scope,cid,'portability.retire_notification',decode(hash,'hex'),'completed',result,clock_timestamp()) ON CONFLICT(workspace_id,client_command_id) DO NOTHING;n:=n+1;
 END LOOP;RETURN n;END $$;REVOKE ALL ON FUNCTION ops.preserve_notification_effects() FROM PUBLIC;
CREATE FUNCTION ops.guard_notification_retirement() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.command_type='portability.retire_notification' AND NOT ops.restore_scope_allowed(NEW.workspace_id) THEN RAISE EXCEPTION 'notification retirement is operator evidence';END IF;RETURN NEW;END $$;
CREATE TRIGGER notification_retirement_guard BEFORE INSERT OR UPDATE ON core.command_receipt FOR EACH ROW EXECUTE FUNCTION ops.guard_notification_retirement();REVOKE ALL ON FUNCTION ops.guard_notification_retirement() FROM PUBLIC;
DO $$ DECLARE d text;BEGIN d:=pg_get_functiondef('ops.apply_private_restore(uuid,bytea,uuid)'::regprocedure);d:=replace(d,'pending:=array_remove(allowed,''core.command_receipt'');','PERFORM ops.preserve_notification_effects();FOR entity IN SELECT e FROM jsonb_array_elements(r.bundle_json->''entities'') e WHERE e->>''kind'' IN (''time.notification_attempt'',''time.notification_provider_event'') LOOP FOR record IN SELECT v FROM jsonb_array_elements(entity->''records'') v LOOP IF NOT ops.provider_history_known(entity->>''kind'',record) THEN RAISE EXCEPTION ''provider history unsupported'';END IF;END LOOP;END LOOP; pending:=array_remove(allowed,''core.command_receipt'');');EXECUTE d;END $$;
